/**
 * Base view for connector administration (owner-only).
 */
export const getConnectorsListUrl = (params?: ConnectorsListParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/connectors/?${stringifiedParams}`
    : `/api/v1/connectors/`;
};

export const connectorsList = async (
  params?: ConnectorsListParams,
  options?: RequestInit,
): Promise<PaginatedConnectorConfigList> => {
  return customFetch<PaginatedConnectorConfigList>(
    getConnectorsListUrl(params),
    {
      ...options,
      method: "GET",
    },
  );
};

